    height, width = len(grid), len(grid[0])
    cells = {(r, c) for r in range(height) for c in range(width) if grid[r][c] == 8}
    pieces = []
    for r in range(height - 1):
        for c in range(width - 1):
            square = {(r + dr, c + dc) for dr in range(2) for dc in range(2)}
            if square <= cells:
                pieces.append((frozenset(square), 1))
            colors = {(r, c): 2, (r, c + 1): 4, (r + 1, c): 3, (r + 1, c + 1): 5}
            for missing in square:
                shape = square - {missing}
                if shape <= cells:
                    pieces.append((frozenset(shape), colors[missing]))
    by_cell = {cell: [] for cell in cells}
    for piece, color in pieces:
        for cell in piece:
            by_cell[cell].append((piece, color))

    def cover(remaining):
        if not remaining:
            return []
        cell = min(remaining, key=lambda p: sum(piece <= remaining for piece, _ in by_cell[p]))
        for piece, color in by_cell[cell]:
            if piece <= remaining:
                rest = cover(remaining - piece)
                if rest is not None:
                    return [(piece, color)] + rest
        return None

    result = [[0 for _ in row] for row in grid]
    for piece, color in cover(cells):
        for r, c in piece:
            result[r][c] = color
    return result
